@startuml

class Ingredient {
  + name : string
  + measuring_unit : string
  + quantity_in_stock : float
}

class Dish {
  + name : string
  + numeric_identifier : int
}

class Table {
  + numeric_identifier : int
  + maximum_amount_of_people : int
}

class Meal {
  + date : date
  + start_time : time
  + end_time : time
}

class Waiter {
  + numeric_identifier : int
  + name : string
  + address : string
  + phone_number : string
}

class Client {
  + tax_identification_number : string
  + name : string
  + address : string
}

class DishMeal {
  + quantity : float
}

Ingredient "1..*" -- "1..*" Dish : composed of
Dish "1" -- "*" DishMeal : consumed in
Meal "1" -- "1..*" DishMeal : contains
Meal "1" -- "1" Table : takes place at
Meal "1" -- "0..1" Client : consumed by
Meal "1" -- "1" Waiter : responsible waiter

@enduml

